func execute_command(command: Dictionary) -> void:
	var cmd_type: String = command.get(\"type\", \"\")
	match cmd_type:
		\"music\":
			var path: String = command.get(\"path\", \"\")
			var fade: float = float(command.get(\"fade\", 1.0))
			var stream: AudioStream = load(path) as AudioStream
			if stream and audio_manager:
				audio_manager.play_music(stream, fade)
		\"stop_music\":
			var fade: float = float(command.get(\"fade\", 1.0))
			if audio_manager:
				audio_manager.stop_music(fade)
		\"sfx\":
			var path: String = command.get(\"path\", \"\")
			var stream: AudioStream = load(path) as AudioStream
			if stream and audio_manager:
				audio_manager.play_sfx(stream)
		\"voice\":
			var path: String = command.get(\"path\", \"\")
			var stream: AudioStream = load(path) as AudioStream
			if stream and audio_manager:
				audio_manager.play_voice(stream)
		\"stop_voice\":
			if audio_manager:
				audio_manager.stop_voice()
		\"wait\":
			var duration: float = float(command.get(\"duration\", 0.0))
			if duration > 0.0:
				await get_tree().create_timer(duration).timeout
		\"shake\":
			var duration: float = float(command.get(\"duration\", 0.2))
			var strength: float = float(command.get(\"strength\", 10.0))
			if character_stage:
				var original_pos: Vector2 = character_stage.position
				var tween := create_tween()
				var steps := int(duration / 0.05)
				for i in range(steps):
					var offset := Vector2(randf_range(-strength, strength), randf_range(-strength, strength))
					tween.tween_property(character_stage, \"position\", original_pos + offset, 0.05)
				tween.tween_property(character_stage, \"position\", original_pos, 0.05)
				await tween.finished
